import { authGuard, createGuard, moduleGuard, permGuard } from './core/auth.guard';
import { HR_ANY } from './core/hr.models';
export const routes = [{
  path: '',
  pathMatch: 'full',
  redirectTo: 'dashboard'
}, {
  path: 'login',
  loadComponent: () => import('./login/login.component').then(m => m.LoginComponent)
}, {
  path: 'dashboard',
  canActivate: [authGuard, permGuard('dashboard.view')],
  loadComponent: () => import('./dashboard/dashboard.component').then(m => m.DashboardComponent)
}, {
  path: 'm/:module',
  canActivate: [authGuard, moduleGuard],
  loadComponent: () => import('./modules/module.component').then(m => m.ModuleComponent)
}, {
  path: 'new/:docType',
  canActivate: [authGuard, createGuard],
  loadComponent: () => import('./documents/doc-form.component').then(m => m.DocFormComponent)
}, {
  path: 'approvals',
  canActivate: [authGuard, permGuard('tasks.act')],
  loadComponent: () => import('./tasks/tasks.component').then(m => m.TasksComponent)
}, {
  path: 'documents',
  canActivate: [authGuard],
  loadComponent: () => import('./requests/requests.component').then(m => m.RequestsComponent)
}, {
  path: 'documents/:id',
  canActivate: [authGuard],
  loadComponent: () => import('./requests/request-detail.component').then(m => m.RequestDetailComponent)
}, {
  path: 'services',
  canActivate: [authGuard],
  loadComponent: () => import('./submit/submit.component').then(m => m.SubmitComponent)
}, {
  path: 'reports',
  canActivate: [authGuard, permGuard('reports.view')],
  loadComponent: () => import('./reports/reports.component').then(m => m.ReportsComponent)
}, {
  path: 'assistant',
  canActivate: [authGuard, permGuard('assistant.use')],
  loadComponent: () => import('./assistant/assistant-page.component').then(m => m.AssistantPageComponent)
}, {
  // HR workspace: every page below is guarded by its own privilege (set per user in Admin > Users)
  path: 'hr',
  canActivate: [authGuard, permGuard(...HR_ANY)],
  loadComponent: () => import('./hr/hr-shell.component').then(m => m.HrShellComponent),
  children: [{
    path: '',
    pathMatch: 'full',
    loadComponent: () => import('./hr/hr-shell.component').then(m => m.HrHomeComponent)
  }, {
    path: 'overview',
    canActivate: [permGuard('hr.reports.view')],
    loadComponent: () => import('./hr/hr-overview.component').then(m => m.HrOverviewComponent)
  }, {
    path: 'employees',
    canActivate: [permGuard('hr.employees.view')],
    loadComponent: () => import('./hr/hr-employees.component').then(m => m.HrEmployeesComponent)
  }, {
    path: 'employees/:id',
    canActivate: [permGuard('hr.employees.view')],
    loadComponent: () => import('./hr/hr-profile.component').then(m => m.HrProfileComponent)
  }, {
    path: 'org',
    canActivate: [permGuard('hr.org.view')],
    loadComponent: () => import('./hr/hr-org.component').then(m => m.HrOrgComponent)
  }, {
    path: 'leave',
    canActivate: [permGuard('hr.leave.view', 'hr.self')],
    loadComponent: () => import('./hr/hr-leave.component').then(m => m.HrLeaveComponent)
  }, {
    path: 'performance',
    canActivate: [permGuard('hr.performance.view', 'hr.self')],
    loadComponent: () => import('./hr/hr-performance.component').then(m => m.HrPerformanceComponent)
  }, {
    path: 'recruitment',
    canActivate: [permGuard('hr.recruitment.view')],
    loadComponent: () => import('./hr/hr-recruitment.component').then(m => m.HrRecruitmentComponent)
  }, {
    path: 'me',
    canActivate: [permGuard('hr.self')],
    loadComponent: () => import('./hr/hr-self.component').then(m => m.HrSelfComponent)
  }]
}, {
  path: 'admin',
  canActivate: [authGuard, permGuard('admin.users', 'org.manage')],
  loadComponent: () => import('./admin/admin.component').then(m => m.AdminComponent)
},
